def climb_stairs_brute(n):
    # f(n) = f(n-1) + f(n-2)：最后一步跨 1 阶或跨 2 阶，两类方案相加
    if n <= 2:
        return n                      # 边界：f(1)=1, f(2)=2
    return climb_stairs_brute(n - 1) + climb_stairs_brute(n - 2)

def climb_stairs_memo(n):
    memo = {}                         # memo[i] 缓存 f(i)，避免重复展开
    def f(i):
        if i <= 2:
            return i                  # 边界：f(1)=1, f(2)=2
        if i not in memo:
            memo[i] = f(i - 1) + f(i - 2)   # 先算再缓存，之后直接查表
        return memo[i]
    return f(n)

def climb_stairs_iter(n):
    if n <= 2:
        return n                      # 边界：dp[1]=1, dp[2]=2
    prev2, prev1 = 1, 2               # 滚动变量：prev2=dp[i-2], prev1=dp[i-1]
    for _ in range(3, n + 1):
        prev2, prev1 = prev1, prev1 + prev2   # 右端用旧值整体右移一位
    return prev1                      # 循环结束时 prev1 即 dp[n]

