class Solution:
    def climbStairs(self, n: int) -> int:
        # 状态定义：dp[i] 表示爬到第 i 阶的方法数
        # 转移方程：dp[i] = dp[i-1] + dp[i-2]
        #   到第 i 阶的最后一步只有两种：从 i-1 走 1 阶，或从 i-2 走 2 阶，
        #   两个来源互不重叠、覆盖全部方案，故直接相加（即斐波那契数列）
        if n <= 2:
            return n                    # 边界：dp[1]=1, dp[2]=2
        prev2, prev1 = 1, 2             # 滚动变量：prev2=dp[i-2], prev1=dp[i-1]
        for _ in range(3, n + 1):
            prev2, prev1 = prev1, prev1 + prev2   # 递推出 dp[i]，整体右移一位
        return prev1                    # 循环结束时 prev1 即 dp[n]

