class Solution {
public:
    int climbStairs(int n) {
        // 状态定义：dp[i] 表示爬到第 i 阶的方法数
        // 转移方程：dp[i] = dp[i-1] + dp[i-2]，最后一步要么跨 1 阶要么跨 2 阶，
        //   两种来源互斥且覆盖全部方案，故直接相加（即斐波那契数列）
        if (n <= 2) return n;          // 边界：dp[1]=1, dp[2]=2
        int prev2 = 1, prev1 = 2;      // 滚动变量：prev2=dp[i-2], prev1=dp[i-1]
        for (int i = 3; i <= n; ++i) {
            int cur = prev1 + prev2;   // 递推出 dp[i]
            prev2 = prev1;             // 整体右移一位
            prev1 = cur;
        }
        return prev1;                  // 循环结束时 prev1 即 dp[n]
    }
};

