from functools import lru_cache

def pascal_memo(numRows):
    @lru_cache(maxsize=None)
    def C(i, j):
        if j == 0 or j == i:
            return 1                  # 每行两端恒为 1
        if j < 0 or j > i:
            return 0                  # 越界视为空格子，配合加法
        return C(i - 1, j - 1) + C(i - 1, j)
    return [[C(i, j) for j in range(i + 1)] for i in range(numRows)]

