class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        // 状态定义：dp[i][j] 表示杨辉三角第 i 行第 j 个数（0 起下标）
        // 转移方程：dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
        // 边界：每行两端 dp[i][0] = dp[i][i] = 1
        vector<vector<int>> dp;
        dp.reserve(numRows);
        for (int i = 0; i < numRows; ++i) {
            vector<int> row(i + 1, 1);      // 第 i 行共 i+1 个数，先全部置 1
            for (int j = 1; j < i; ++j)     // 两端保持 1，只递推中间 j=1..i-1
                row[j] = dp[i - 1][j - 1] + dp[i - 1][j];
            dp.push_back(std::move(row));   // 当前行存入，成为下一行的『上一行』
        }
        return dp;
    }
};

