def rob_memo(nums):
    n = len(nums)
    memo = {0: 0, 1: nums[0] if n else 0}   # 边界：rob(0)=0, rob(1)=nums[0]
    def rob(i):
        if i in memo:
            return memo[i]
        # 不偷第 i 间 -> rob(i-1)；偷第 i 间 -> rob(i-2) + nums[i-1]
        memo[i] = max(rob(i - 1), rob(i - 2) + nums[i - 1])
        return memo[i]
    return rob(n)

def rob_rolling(nums):
    prev2, prev1 = 0, 0               # prev2=dp[i-2], prev1=dp[i-1]
    for x in nums:
        prev2, prev1 = prev1, max(prev1, prev2 + x)   # 右端全读旧值
    return prev1                      # 考虑完全部房屋，prev1 即 dp[n]

