def rob_circle_memo(nums):
    n = len(nums)
    if n == 1:
        return nums[0]                # 单间房不构成环形约束
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i, prev_stolen, took_first):
        if i == n:
            return 0                  # 没有房子可考虑
        best = dfs(i + 1, False, took_first)          # 不偷第 i 间
        can_steal = not prev_stolen and not (i == n - 1 and took_first)
        if can_steal:                 # 上一间没偷、且尾间未被首间封禁
            best = max(best, nums[i] + dfs(i + 1, True, took_first or i == 0))
        return best
    return dfs(0, False, False)

def rob_circle_table(nums):
    if len(nums) == 1:
        return nums[0]                # 特判：切片会丢掉唯一的房子

    def rob_linear(houses):
        n = len(houses)
        dp = [0] * (n + 1)            # dp[i] = 考虑前 i 间的最高金额
        if n:
            dp[1] = houses[0]
        for i in range(2, n + 1):
            dp[i] = max(dp[i - 1], dp[i - 2] + houses[i - 1])
        return dp[n]

    return max(rob_linear(nums[1:]), rob_linear(nums[:-1]))   # 两情形取 max

def rob_circle_rolling(nums):
    if len(nums) == 1:
        return nums[0]                # 特判：单间房不构成环形约束

    def rob_linear(houses):
        prev2, prev1 = 0, 0           # dp[i-2], dp[i-1]，同 198
        for x in houses:
            prev2, prev1 = prev1, max(prev1, prev2 + x)
        return prev1

    return max(rob_linear(nums[1:]), rob_linear(nums[:-1]))

