class Solution:
    def rob(self, nums: List[int]) -> int:
        # 环形处理：房屋围成圈，首尾相邻不能同偷
        # 拆环成链：按『首间偷不偷』分成两个互斥的线性情形——
        #   情形 A：不偷首间 -> 等价于线性打家劫舍 nums[1:]
        #   情形 B：不偷尾间 -> 等价于线性打家劫舍 nums[:-1]
        if len(nums) == 1:
            return nums[0]              # 特判：单间房不构成环形约束，切片会丢解

        def rob_linear(houses: List[int]) -> int:
            # 状态定义：dp[i] = 考虑前 i 间房能偷到的最高金额（同 198 题）
            # 转移方程：dp[i] = max(dp[i-1], dp[i-2] + houses[i-1])
            prev2, prev1 = 0, 0         # 滚动变量：prev2=dp[i-2], prev1=dp[i-1]
            for x in houses:
                prev2, prev1 = prev1, max(prev1, prev2 + x)
            return prev1

        # 两情形互斥且合起来覆盖所有合法方案，取较大者
        return max(rob_linear(nums[1:]), rob_linear(nums[:-1]))

