class Solution {
public:
    int rob(vector<int>& nums) {
        // 环形处理：房屋围成圈，首尾相邻不能同偷
        // 拆环成链：情形 A 不偷首间 -> 线性打家劫舍 nums[1..n)；
        //           情形 B 不偷尾间 -> 线性打家劫舍 nums[0..n-1)
        int n = nums.size();
        if (n == 1) return nums[0];    // 特判：单间房不构成环形约束，切片会丢解
        auto robLinear = [](const vector<int>& houses) {
            // 状态定义：dp[i] = 前 i 间房最高金额（同 198 题）
            // 转移方程：dp[i] = max(dp[i-1], dp[i-2] + houses[i-1])
            int prev2 = 0, prev1 = 0;  // 滚动变量：dp[i-2], dp[i-1]
            for (int x : houses) {
                int cur = max(prev1, prev2 + x);
                prev2 = prev1;         // 整体右移一位
                prev1 = cur;
            }
            return prev1;
        };
        // 两情形互斥且合起来覆盖所有合法方案，取较大者
        vector<int> skipFirst(nums.begin() + 1, nums.end());
        vector<int> skipLast(nums.begin(), nums.end() - 1);
        return max(robLinear(skipFirst), robLinear(skipLast));
    }
};

