// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（房屋数，房屋围成一圈）
//   第二行：n 个非负整数（每间房的现金）
// 输出格式：一行一个整数，今晚能偷到的最高金额
#include <bits/stdc++.h>
using namespace std;

// 线性打家劫舍：dp[i] = max(dp[i-1], dp[i-2] + houses[i-1])，同 198 题
int robLinear(const vector<int>& houses) {
    int prev2 = 0, prev1 = 0;          // 滚动变量：dp[i-2], dp[i-1]
    for (int x : houses) {
        int cur = max(prev1, prev2 + x);
        prev2 = prev1;                 // 整体右移一位
        prev1 = cur;
    }
