class Solution {
    public int rob(int[] nums) {
        // 环形处理：房屋围成圈，首尾相邻不能同偷
        // 拆环成链：按『首间偷不偷』分成两个互斥的线性情形，取较大者
        if (nums.length == 1) return nums[0];  // 单间房不构成环形约束
        return Math.max(robLinear(nums, 1, nums.length),     // 情形 A：不偷首间
                        robLinear(nums, 0, nums.length - 1)); // 情形 B：不偷尾间
    }

    // 线性打家劫舍（同 198）：dp[i] = max(dp[i-1], dp[i-2] + nums[i])
    private int robLinear(int[] nums, int from, int to) {
        int prev2 = 0, prev1 = 0;      // 滚动变量：dp[i-2], dp[i-1]
        for (int i = from; i < to; i++) {
            int cur = Math.max(prev1, prev2 + nums[i]);
            prev2 = prev1;             // 整体右移一位
            prev1 = cur;
        }
        return prev1;
    }
}

