func rob(nums []int) int {
	// 环形处理：房屋围成圈，首尾相邻不能同偷
	// 拆环成链：按『首间偷不偷』分成两个互斥的线性情形，取较大者
	n := len(nums)
	if n == 1 {
		return nums[0] // 单间房不构成环形约束，切片会丢解
	}
	robLinear := func(houses []int) int {
		// 线性打家劫舍（同 198）：dp[i] = max(dp[i-1], dp[i-2]+houses[i-1])
		prev2, prev1 := 0, 0 // 滚动变量：dp[i-2], dp[i-1]
		for _, x := range houses {
			cur := max(prev1, prev2+x)
			prev2, prev1 = prev1, cur // 整体右移一位
		}
		return prev1
	}
	// 情形 A 不偷首间 -> nums[1:]；情形 B 不偷尾间 -> nums[:n-1]
	return max(robLinear(nums[1:]), robLinear(nums[:n-1]))
}

