	// 转移方程：cur = max(x, cur + x)，前段为负贡献时舍弃并从 x 重开一段
	cur, best := nums[0], nums[0]  // 初值对应 dp[0] = nums[0]，best 记录全局答案
	for _, x := range nums[1:] {
