class Solution {
public:
    int maxProduct(vector<int>& nums) {
        // 状态定义：fmax/fmin = 以当前元素结尾的子数组的最大/最小乘积（滚动维护）
        // 为何要维护最小：负负得正，当前最小负值乘下一个负数可能反超最大值
        // 转移方程：从三候选 {x, fmax*x, fmin*x}（新开段/续最大/续最小）取 max 与 min
        long long fmax = 1, fmin = 1;  // 乘法单位元 1 作初值，首个元素自然并入
        long long best = LLONG_MIN;    // 负无穷哨兵用 LLONG_MIN，防止极端值下溢出
        for (int x : nums) {
            long long v = x;
            long long a = v, b = fmax * v, c = fmin * v;  // 三个候选一次算全
            fmax = max({a, b, c});     // 先算候选再同时赋值，避免用到已覆盖旧值
            fmin = min({a, b, c});
            best = max(best, fmax);    // 答案取所有位置最大分量的最大值
        }
        return (int)best;
    }
};

