def word_break_memo(s, wordDict):
    words = set(wordDict)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i):
        if i == len(s):
            return True               # 空串视为可拆，递归出口
        # 枚举『下一个单词』w：s 以 w 开头则归约到更短后缀
        return any(s.startswith(w, i) and dfs(i + len(w)) for w in words)
