class Solution {
public:
    bool wordBreak(string s, vector<string>& wordDict) {
        // 状态定义：dp[i] 表示 s 的前 i 个字符 s[0..i) 能否被字典拆分
        // 转移方程：dp[i] = true 当且仅当存在词长 L，使 dp[i-L] 为真
        //   且 s[i-L..i) 在字典中（把『拼接』反过来想成『切分』）
        unordered_set<string> words(wordDict.begin(), wordDict.end());  // O(1) 判单词
        unordered_set<int> lens;       // 只枚举出现过的词长，剪掉无效切分位置
        for (const string& w : wordDict) lens.insert((int)w.size());
        int n = (int)s.size();
        vector<bool> dp(n + 1, false);
        dp[0] = true;                  // 边界：空前串视为可拆分，是递推的种子
        for (int i = 1; i <= n; ++i) {
            for (int L : lens) {       // 枚举『最后一个单词』的长度
                if (L <= i && dp[i - L] && words.count(s.substr(i - L, L))) {
                    dp[i] = true;      // 前 i-L 个字符可拆 + 末段是单词 -> 可拆
                    break;             // 找到一种拆法即可，提前结束内层循环
                }
            }
        }
        return dp[n];
    }
};

