func wordBreak(s string, wordDict []string) bool {
	// 状态定义：dp[i] 表示 s 的前 i 个字符 s[:i] 能否被字典拆分
	// 转移方程：dp[i] = true 当且仅当存在词长 L，使 dp[i-L] 为真
	//   且 s[i-L:i] 在字典中（把『拼接』反过来想成『切分』）
	words := map[string]bool{}     // 哈希集合：O(1) 判断子串是否为字典单词
	lens := map[int]bool{}         // 只枚举出现过的词长，剪掉无效切分位置
	for _, w := range wordDict {
		words[w] = true
		lens[len(w)] = true
	}
	n := len(s)
	dp := make([]bool, n+1)
	dp[0] = true                   // 边界：空前串视为可拆分，是递推的种子
	for i := 1; i <= n; i++ {
		for L := range lens {      // 枚举『最后一个单词』的长度
			if L <= i && dp[i-L] && words[s[i-L:i]] {
				dp[i] = true       // 前 i-L 个字符可拆 + 末段是单词 -> 可拆
				break              // 找到一种拆法即可，提前结束内层循环
			}
		}
	}
	return dp[n]
}

