def coin_change_brute(coins, amount):
    def f(a):
        if a == 0:
            return 0                  # 金额 0 不需要硬币
        if a < 0:
            return float('inf')       # 负金额不可达
        # 最后一枚硬币是 c：1 + f(a-c)，所有面额取最小
        return 1 + min(f(a - c) for c in coins)
    ans = f(amount)
    return ans if ans != float('inf') else -1

def coin_change_memo(coins, amount):
    memo = {0: 0}                     # f(0)=0 是递归出口
    def f(a):
        if a < 0:
            return float('inf')       # 负金额不可达
        if a not in memo:
            memo[a] = 1 + min(f(a - c) for c in coins)
        return memo[a]
    ans = f(amount)
    return ans if ans != float('inf') else -1

def coin_change_dp(coins, amount):
    INF = amount + 1                  # 表示凑不出：合法方案枚数 <= amount
    dp = [INF] * (amount + 1)
    dp[0] = 0                         # 金额 0 用 0 枚，递推种子
    for i in range(1, amount + 1):
        for c in coins:               # 枚举最后一枚硬币的面额
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

