class Solution {
public:
    int coinChange(vector<int>& coins, int amount) {
        // 状态定义：dp[i] = 凑出金额 i 所需的最少硬币枚数
        // 转移方程：dp[i] = min(dp[i-c] + 1)，对所有面额 c <= i
        //   （『最后一枚硬币』若是面额 c，则剩余 i-c 由子问题最优解决）
        const long long INF = amount + 1LL;  // 「凑不出」哨兵：合法方案枚数必 <= amount
        vector<long long> dp(amount + 1, INF);
        dp[0] = 0;                     // 边界：金额 0 不需要任何硬币，是递推种子
        for (int i = 1; i <= amount; ++i) {
            for (int c : coins) {      // 枚举最后一枚硬币的面额
