def lis_memo(nums):
    n = len(nums)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dfs(i):
        best = 1                      # 至少含 nums[i] 自己
        for j in range(i + 1, n):
            if nums[j] > nums[i]:     # 严格递增：相等不能接
                best = max(best, 1 + dfs(j))
        return best
    return max(dfs(i) for i in range(n))

def lis_binary(nums):
    dp = []                           # dp[k] = 长度 k+1 的 LIS 的最小结尾元素
    for x in nums:
        lo, hi = 0, len(dp)           # 在 [lo, hi) 内找第一个 >= x 的下标
        while lo < hi:
            mid = (lo + hi) // 2
            if dp[mid] < x:
                lo = mid + 1          # dp[mid] < x：可行位置在右侧
            else:
                hi = mid              # dp[mid] >= x：答案在左侧（含 mid）
        if lo == len(dp):
            dp.append(x)              # x 比所有结尾大：LIS 增长 1
        else:
            dp[lo] = x                # 替换：让该长度结尾更小、更易扩展
    return len(dp)

