class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # 贪心 + 二分（O(n log n) LIS 模板）
        # 状态定义：dp[k] = 所有长度为 k+1 的严格递增子序列中最小的结尾元素
        #   （贪心：同长度下结尾越小，越容易被后续元素扩展）
        # dp 单调递增 -> 对每个 x 二分找第一个 >= x 的位置：替换或追加
        dp = []
        for x in nums:
            lo, hi = 0, len(dp)         # 在 [lo, hi) 内找第一个 >= x 的下标
            while lo < hi:
                mid = (lo + hi) // 2
                if dp[mid] < x:
                    lo = mid + 1        # dp[mid] < x：可行位置在右侧
                else:
                    hi = mid            # dp[mid] >= x：答案在左侧（含 mid）
            if lo == len(dp):
                dp.append(x)            # x 比所有结尾都大：LIS 长度增加 1
            else:
                dp[lo] = x              # 用更小的 x 替换，让后续元素更容易接上
        return len(dp)                  # dp 的长度即 LIS 长度（dp 内容不一定是某个 LIS）

