class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        // 贪心 + 二分（O(n log n) LIS 模板）
        // 状态定义：dp[k] = 所有长度为 k+1 的严格递增子序列中最小的结尾元素
        //   （贪心：同长度下结尾越小，越容易被后续元素扩展）
        vector<int> dp;                // dp 单调递增，长度即当前 LIS 长度
        for (int x : nums) {
            // 对每个 x 二分找 dp 中第一个 >= x 的位置：替换或追加
            auto it = lower_bound(dp.begin(), dp.end(), x);
            if (it == dp.end())
                dp.push_back(x);       // x 比所有结尾都大：LIS 长度增加 1
            else
                *it = x;               // 用更小的 x 替换，让后续元素更容易接上
        }
        return (int)dp.size();         // dp 的长度即 LIS 长度（内容不一定是某个 LIS）
    }
};

