class Solution {
    public int lengthOfLIS(int[] nums) {
        // 贪心 + 二分（O(n log n) LIS 模板）
        // 状态定义：dp[k] = 所有长度为 k+1 的严格递增子序列中最小的结尾元素
        //   （贪心：同长度下结尾越小，越容易被后续元素扩展）
        int[] dp = new int[nums.length];
        int len = 0;                   // 当前 LIS 长度，dp 的有效区间为 [0, len)
        for (int x : nums) {
            int lo = 0, hi = len;      // 在 [lo, hi) 内找第一个 >= x 的下标
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;    // 无符号右移，防 lo+hi 相加溢出
                if (dp[mid] < x) lo = mid + 1;   // dp[mid] < x：可行位置在右侧
                else hi = mid;                   // dp[mid] >= x：答案在左侧（含 mid）
            }
            dp[lo] = x;                // lo==len 时等价于追加，否则用更小的 x 替换
            if (lo == len) len++;      // x 比所有结尾都大：LIS 长度增加 1
        }
        return len;
    }
}

